package com.stockshield.service;
import com.stockshield.dto.SimulationRequest; import com.stockshield.entity.Product; import com.stockshield.repository.ProductRepository; import org.springframework.stereotype.Service; import java.util.*; import java.util.concurrent.*; import java.util.concurrent.atomic.*;
@Service public class SimulationService {private final ProductRepository products; private final OrderService orders; public SimulationService(ProductRepository p,OrderService o){products=p;orders=o;} public Map<String,Object> run(SimulationRequest r){Product p=products.findById(r.productId()).orElseThrow(); if(p.getInventory()!=r.initialInventory()){products.findLockedById(p.getId()).ifPresent(x->{x.setInventory(r.initialInventory());x.setInitialInventory(r.initialInventory());});} ExecutorService pool=Executors.newFixedThreadPool(r.threads()); AtomicInteger submitted=new AtomicInteger(); long start=System.nanoTime(); List<Future<?>> fs=new ArrayList<>(); for(int i=0;i<r.customers();i++){final int n=i;fs.add(pool.submit(()->{submitted.incrementAndGet();String key="SIM-"+n+"-"+UUID.randomUUID();orders.createAndSubmit(r.productId(),r.quantity(),key);}));} fs.forEach(f->{try{f.get();}catch(Exception ignored){}});pool.shutdown();try{pool.awaitTermination(60,TimeUnit.SECONDS);}catch(InterruptedException e){Thread.currentThread().interrupt();} long ms=(System.nanoTime()-start)/1_000_000; Product fresh=products.findById(r.productId()).orElseThrow();long success=orders.count(com.stockshield.entity.Order.Status.SUCCESS);long out=orders.count(com.stockshield.entity.Order.Status.OUT_OF_STOCK);long dlq=orders.count(com.stockshield.entity.Order.Status.DLQ);long retry=orders.count(com.stockshield.entity.Order.Status.RETRYING);return new LinkedHashMap<>(Map.of("totalRequests",r.customers(),"submitted",submitted.get(),"successfulOrders",success,"outOfStockOrders",out,"retryingOrders",retry,"dlqOrders",dlq,"currentInventory",fresh.getInventory(),"processingTimeMs",ms,"requestsPerSecond",ms==0?0.0:(r.customers()*1000.0/ms),"negativeInventory",Math.max(0,-fresh.getInventory()),"overselling",Math.max(0,(r.customers()*r.quantity())-r.initialInventory()-out*r.quantity())));}}
